// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper callee that always succeeds for low-level call with selector transferFrom
    contract CalleeGood {
        // match signature transferFrom(address,address,uint256)
        function transferFrom(address, address, uint) external pure returns (bool) {
            return true;
        }
        // fallback to accept any other calls as success
        fallback() external payable {}
        receive() external payable {}
    }

    function setUp() public { c = new C(); }

    // fuzz parameters: from address, caddress (we will deploy a CalleeGood and pass its address),
    // array of to-addresses and value v
    function testFuzz_property(address from, address /* dummy */, address[] memory _tos, uint256 v) public {
        // keep tos non-empty (admissible domain as require in contract)
        vm.assume(_tos.length > 0);

        // deploy a helper callee which will make the low-level call succeed (so transfer does not revert)
        CalleeGood g = new CalleeGood();

        // call transfer and observe its return via try/catch to capture non-revert success
        bool ok;
        bool ret;
        try c.transfer(from, address(g), _tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The reference implementation always returns true on successful (non-reverting) calls.
        // Assert that if the call did not revert (ok == true) then the returned value is true.
        assertTrue(!ok || ret);
    }
}

