pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: from address and number of tos (to be expanded into an array), and a uint value
    function testFuzz_property(address from, uint96 nTos, uint256 v) public {
        // keep number of tos reasonably bounded but allow zero to be excluded by vm.assume
        uint256 tosCount = uint256(nTos) % 8; // small array up to 7 elements
        vm.assume(tosCount > 0); // admissible domain: _tos.length > 0 required by contract

        // Deploy a simple callee that always succeeds on the called selector
        // The external callee must implement a function matching transferFrom(address,address,uint256)
        // We'll deploy one and pass its address as caddress
        GoodCallee cal = new GoodCallee();

        // build tos array with distinct addresses derived from fuzzed `from` and index
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // derive pseudo-random addresses from from and i so fuzzer still controls 'from'
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i)))));
        }

        // call transfer and capture whether it returns true for the successful non-reverting case
        bool ok;
        try c.transfer(from, address(cal), tos, v) returns (bool ret) {
            // call completed without revert; record the returned value
            ok = ret;
        } catch {
            // call reverted; record as not-ok (but our property concerns completions)
            ok = false;
        }

        // Property: for any admissible input where transfer completes (no revert), reference C returns true.
        // We observe completion by checking that the call did not revert AND that the returned bool is true.
        // Because this test runs against the reference contract, ok must be true for all admissible inputs.
        assertTrue(ok);
    }
}

// Minimal adversarial callee that always succeeds when called with the expected selector
contract GoodCallee {
    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: from address, callee address (we will deploy a helper and pass its address),
    // an array length and a value v. We can't fuzz an array directly here in solidity signature,
    // so we fuzz a single address element and an array length and construct the array.
    function testFuzz_property(address from, uint256 v, address tosElem, uint256 tosLen) public {
        // admissible domain: tosLen should be treated as a uint for array length > 0 to avoid revert from require(_tos.length > 0)
        // keep domain wide but ensure tosLen fits reasonable bounds
        tosLen = bound(tosLen, 1, 10);

        // deploy a simple callee that always succeeds on call (returns true) to exercise the normal successful path
        GoodCallee good = new GoodCallee();

        // build the tos array in memory
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            tos[i] = tosElem;
        }

        // call transfer and observe whether it completes (no revert) and if so the returned value
        bool ok;
        try c.transfer(from, address(good), tos, v) returns (bool ret) {
            // record that call completed successfully and check returned value equals true
            ok = ret;
        } catch {
            // if it reverts, we treat ok as false — but the reference contract only reverts when tos.length == 0
            ok = false;
        }

        // The universal property: for all admissible inputs (tosLen >= 1), the reference returns true (ok == true).
        // This single assertion reads c's observable behavior (the return via try/catch) and will fail on the mutant
        // which returns false for completing calls.
        assertTrue(ok);
    }
}

// Minimal helper callee that returns true for the encoded selector call
contract GoodCallee {
    // implement a fallback that decodes transferFrom(address,address,uint256) call signature and returns true
    fallback() external payable returns (bytes memory) {
        // Always succeed; no revert. Return empty data. The caller only checks the low-level call success.
        return "";
    }
}

