pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address and a dynamic array length and an arbitrary value
    function testFuzz_property(address from, uint256 v, uint8 tosLen) public {
        // keep tosLen in a reasonable (but still wide) range and ensure non-empty per contract requirement
        tosLen = uint8(bound(tosLen, 1, 8));

        // prepare tos array and deploy a benign callee that always returns true on the low-level call
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // deploy a simple callee that returns true for the selector called
            TosReceiver ok = new TosReceiver();
            tos[i] = address(ok);
        }

        // call transfer and observe whether it completes and returns true
        bool ok;
        try c.transfer(from, tos[0], tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for any admissible input (non-empty tos) the reference returns true on successful completion
        // Single assertion reading c's public behavior: the call should have returned true (ok == true)
        assertTrue(ok);
    }
}

// Minimal benign callee: responds to the selector and returns successfully
contract TosReceiver {
    fallback() external payable {
        // do nothing, succeed
    }
    receive() external payable {}
}
